--
-- Table structure for table `login`
--

DROP TABLE IF EXISTS `login`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `login` (
  `id_user` int NOT NULL AUTO_INCREMENT,
  `username` varchar(30) DEFAULT NULL,
  `email` varchar(70) DEFAULT NULL,
  `senha` varchar(45) DEFAULT NULL,
  `excluido` tinyint DEFAULT NULL,
  `entregador_id_entregador` int DEFAULT NULL,
  `restaurante_id_restaurante` int DEFAULT NULL,
  `cliente_id_cliente` int DEFAULT NULL,
  PRIMARY KEY (`id_user`),
  UNIQUE KEY `username_UNIQUE` (`username`),
  UNIQUE KEY `email_UNIQUE` (`email`),
  KEY `fk_login_entregador1_idx` (`entregador_id_entregador`),
  KEY `fk_login_restaurante1_idx` (`restaurante_id_restaurante`),
  KEY `fk_login_cliente1_idx` (`cliente_id_cliente`),
  CONSTRAINT `fk_login_cliente1` FOREIGN KEY (`cliente_id_cliente`) REFERENCES `cliente` (`id_cliente`),
  CONSTRAINT `fk_login_entregador1` FOREIGN KEY (`entregador_id_entregador`) REFERENCES `entregador` (`id_entregador`),
  CONSTRAINT `fk_login_restaurante1` FOREIGN KEY (`restaurante_id_restaurante`) REFERENCES `restaurante` (`id_restaurante`)
) ENGINE=InnoDB AUTO_INCREMENT=701 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

